-- bee-lpm-project-space-seed: creates "Bee LPM" as a real OpenLPM home, following the
-- same pattern already proven for "one topic, two languages" in this app (EvoMentor /
-- EvoMentor-Thuringia, migration 015/074): a pure-container parent project plus two
-- fully independent, fully-content-bearing child projects, linked only by
-- parent_project_id (never forced governance or vocabulary coupling, same RFC-0010-
-- derived precedent). No shared bilingual-field mechanism is used (content_translations
-- was designed in proposals/0005-multi-language-content.md but never actually built --
-- see 074's own comment -- so this migration does not depend on it).
--
-- Content is transcribed from the bee-k12 GitHub repo's /lpm/ tree (six strands, ~29
-- BEE-K12-v0.1.0 vocabulary concepts, seven age-based grade bands GB-0..GB-6), already
-- bilingual at the source -- this migration's real job is splitting that single
-- bilingual source into two independently addressable project spaces of equal depth,
-- not inventing new content. Generated by scripts/generate_bee_lpm_seed.mjs, not
-- hand-typed. Both child projects seeded is_private = TRUE / maturity = 'draft': this is
-- AI-transcribed, not yet human-expert-reviewed content (bee-k12's own epistemicStatus:
-- designed-thought-experiment, unchanged here), same default every other early-stage
-- OpenLPM project uses until a real review gate is cleared.
--
-- Idempotency: all ids are uuid5-derived (stable across re-runs); lpm_schema_elements
-- and lpm_data_objects inserts use ON CONFLICT (id) DO NOTHING, lpm_connections/
-- lpm_object_tags use their own real unique constraints -- safe to re-apply.

DO $MIGRATION$
DECLARE
  v_parent_id UUID := '73a2bd4e-3ced-5d45-95cb-0342c246cb69';
  v_en_id UUID := '27b8e93e-75b9-5f29-af04-713661212e8f';
  v_de_id UUID := '6c0f1109-a2e0-54aa-a092-ee480b249454';
  v_user_id UUID;
BEGIN

  SELECT id INTO v_user_id FROM users WHERE email = 'dustin.eirdosh@eva.mpg.de';

  -- ==========================================================================
  -- Parent: Bee LPM (pure container, no own content -- see header note)
  -- ==========================================================================
  INSERT INTO projects (id, slug, name, description, status, epistemic_status, epistemic_status_note, hosting_mode, is_private, maturity, parent_project_id, focus_type, region_tags, theme_tags, working_languages)
  VALUES (
    v_parent_id, 'bee-lpm', $J$Bee LPM$J$,
    $J$A six-strand K-12 learning progression built around bees -- cooperation and division of labor in the hive, ecological interdependence through pollination, the economics and law of a managed resource, bee cognition and swarm intelligence, the evolutionary origins of cooperation, and apiculture as craft and management philosophy. Organizational home only: this project holds no content of its own. Each language has its own fully independent, independently-authored project space -- see bee-lpm-en / bee-lpm-de -- following the same pattern already proven for EvoMentor / EvoMentor-Thuringia (migration 015/074), not a shared bilingual-field design.$J$,
    'active', 'designed-thought-experiment',
    $J$Migrated from the standalone bee-k12 GitHub repo (a real work-draft report for one pilot site -- a Waldorf school in Sachsen with a school apiary -- not an arbitrary synthetic construction, but not yet field-tested or formally reviewed, per RFC-0019). Status carried over unchanged from that repo's own lpm.yaml.$J$,
    'hosted', TRUE, 'draft', NULL, 'thematic', '{}'::TEXT[], ARRAY['bees','interdisciplinary']::TEXT[], ARRAY['en','de']::TEXT[]
  )
  ON CONFLICT (slug) DO NOTHING;

  IF v_user_id IS NOT NULL THEN
    INSERT INTO project_members (project_id, user_id, role) VALUES (v_parent_id, v_user_id, 'owner') ON CONFLICT (project_id, user_id) DO NOTHING;
    UPDATE projects SET created_by = v_user_id WHERE id = v_parent_id AND created_by IS NULL;
  END IF;

  -- ==========================================================================
  -- Child: Bee LPM (English)
  -- ==========================================================================
  INSERT INTO projects (id, slug, name, description, status, epistemic_status, epistemic_status_note, hosting_mode, is_private, maturity, parent_project_id, focus_type, region_tags, theme_tags, working_languages)
  VALUES (
    v_en_id, 'bee-lpm-en', $J$Bee LPM (English)$J$,
    $J$The English-language Bee LPM: six strands (The Hive as Superorganism; Bees & Ecological Interdependence; The Economics & Law of a Managed Resource; Bee Cognition & Swarm Intelligence; Bees Through Deep Time; Apiculture as Craft & Management Philosophy), each spanning seven age-based grade bands (GB-0 early childhood through GB-6 upper secondary). Standards-neutral by design -- no grade-numbering or standards-system language is baked into the content itself; a crosswalk layer mapping onto specific school systems lives in the bee-lpm GitHub repo, not here.$J$,
    'active', 'designed-thought-experiment',
    $J$Migrated from the standalone bee-k12 GitHub repo's bilingual /lpm/ tree, this language's fields only. Not field-tested or formally reviewed as curriculum -- designed-thought-experiment per RFC-0019, unchanged from the source repo's own status.$J$,
    'hosted', TRUE, 'draft', v_parent_id, 'thematic', '{}'::TEXT[], ARRAY['bees','interdisciplinary']::TEXT[], ARRAY['en']::TEXT[]
  )
  ON CONFLICT (slug) DO NOTHING;

  INSERT INTO project_base_links (project_id, base_repo, can_import, can_propose_pr) VALUES (v_en_id, 'conceptbase', TRUE, FALSE) ON CONFLICT (project_id, base_repo) DO NOTHING;

  INSERT INTO project_source_declarations (project_id, source_name, format, license_or_rights_note, url)
  SELECT v_en_id, $J$bee-k12 (GitHub repo, retired after this migration -- moved to the new bee-lpm GitHub repo for non-LPM content)$J$, $J$YAML (ConceptBase oe:LPM / oe:Strand schema)$J$, $J$CC-BY-4.0 (bee-k12's own license, LICENSE-CONTENT). Migrated from the standalone bee-k12 GitHub repo into this Project Space, preserving its content and provenance; structurally imported into lpm_data_objects/lpm_connections/lpm_object_tags by this migration, not merely declared.$J$, $J$https://github.com/openevo-ccs/bee-lpm$J$
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en_id AND source_name = $J$bee-k12 (GitHub repo, retired after this migration -- moved to the new bee-lpm GitHub repo for non-LPM content)$J$);

  IF v_user_id IS NOT NULL THEN
    INSERT INTO project_members (project_id, user_id, role) VALUES (v_en_id, v_user_id, 'owner') ON CONFLICT (project_id, user_id) DO NOTHING;
    UPDATE projects SET created_by = v_user_id WHERE id = v_en_id AND created_by IS NULL;
  END IF;

  -- Concept vocabulary (BEE-K12-v0.1.0)
  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
  VALUES
  ('a1fa6ff1-3d5d-5139-b728-dd6b6e08aa20', v_en_id, 'concept', $J$Colony as Superorganism$J$, $J$A colony of eusocial insects whose members are functionally interdependent enough that the colony as a whole shows properties — coordinated decision-making, growth, self-repair, reproduction — more naturally attributed to a single organism than to any one of its individual members.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-superorganism","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('178a0e80-1d67-54b0-82f2-008260101db3', v_en_id, 'concept', $J$Division of Labor (Age Polyethism)$J$, $J$Within a colony, individuals take on different tasks — often shifting in a predictable sequence as they age (nurse, builder, forager) — so the colony's total workload is distributed rather than every member performing every task.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-division-of-labor","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('110e6341-2f5e-5420-98d9-b909a603983a', v_en_id, 'concept', $J$Waggle Dance Communication$J$, $J$A patterned figure-eight dance by which a returning forager encodes the direction and distance of a resource (a food source or a candidate nest site) for her hive-mates — decoded by Karl von Frisch (1973 Nobel Prize in Physiology or Medicine, shared with Konrad Lorenz and Niko Tinbergen).
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-waggle-dance-communication","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('baad57ba-4412-5e51-b142-e4844e041f2f', v_en_id, 'concept', $J$Swarm Nest-Site Decision-Making$J$, $J$A decentralized process — competing scout waggle dances and a quorum threshold — by which a honeybee swarm collectively selects a single new nest site without any individual directing the choice.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-swarm-decision-making","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('6e0f6694-0932-5dcc-9177-19a3d6568a08', v_en_id, 'concept', $J$Major Transitions in Individuality$J$, $J$The evolutionary process by which formerly independent, self-replicating units (e.g. individual insects) come to reproduce and compete as a single higher-level unit, with conflict among the lower-level units suppressed enough that natural selection acts predominantly on the higher-level unit.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-major-transitions-individuality","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('bfcebc87-223e-5580-943e-871c39053795', v_en_id, 'concept', $J$Pollination$J$, $J$The transfer of pollen from a flower's male structures to a receptive female structure — often on another individual plant — enabling fertilization and seed/fruit production. Animal pollination (by bees among many other species) is one of several transfer mechanisms alongside wind and water.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-pollination","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('290c24c8-49cc-5748-a733-df951553769a', v_en_id, 'concept', $J$Pollination Dependency$J$, $J$The degree to which a food crop's yield relies on animal pollination rather than self- or wind-pollination — ranging from crops with no dependency to crops (e.g. almonds) that fail almost entirely without it.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-pollination-dependency","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('517b3e93-2f9b-5dd7-9840-cb146742e588', v_en_id, 'concept', $J$Ecosystem Service$J$, $J$A benefit humans obtain from an ecosystem's ongoing biological processes — here, animal pollination of food and fiber crops — rather than from a good humans have manufactured directly.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-ecosystem-service","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('5bab89b1-2ffe-5730-a5eb-6866fa1df41e', v_en_id, 'concept', $J$Managed vs. Wild Pollinators$J$, $J$The distinction between honeybee colonies actively kept and transported by beekeepers for pollination services and the much larger diversity of wild bee, other insect, and vertebrate pollinator species — and the tradeoffs of relying on the former to substitute for decline in the latter.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-managed-vs-wild-pollinators","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('fade3c3c-18a3-54ea-a2dd-360a27a042ab', v_en_id, 'concept', $J$Colony and Pollinator Decline$J$, $J$The multi-causal decline of managed honeybee colonies and wild pollinator populations (habitat loss, pesticide exposure, parasites/pathogens such as Varroa destructor, and climate change) and its downstream consequences for food-crop yields and food security.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-colony-and-pollinator-decline","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('0dd5a7db-22da-57f6-9e46-1355013b6f92', v_en_id, 'concept', $J$Pollination Markets$J$, $J$The buying and selling of pollination as a service — most visibly, beekeepers trucking managed colonies to farms (e.g. the California almond harvest) for a fee rather than a farm relying on pollination occurring incidentally.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-pollination-markets","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('67773bec-a3ee-53a6-8709-4a9e5d9d993c', v_en_id, 'concept', $J$Zeidler Guild Law$J$, $J$The dedicated guild, court, and special legal rights medieval Zeidler (wild/semi-wild forest honey-gatherers) developed — honey and wax being valuable enough, as Europe's main sweetener and candle material before cane sugar, to warrant their own governance rather than falling under general trade law.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-zeidler-guild-law","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('bd68a1eb-35ba-5a97-9e80-d35faf93b4cb', v_en_id, 'concept', $J$Substitute-Good Displacement$J$, $J$What happens to a trade, product, or regional economy when a substitute good displaces the original — as cane sugar (and later sugar-beet cultivation) eliminated nearly all of Zeidlerei's economic importance in Europe.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-substitute-good-displacement","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('8a1428f1-de73-503a-a6a7-454196be8868', v_en_id, 'concept', $J$Apiary Risk & Insurance$J$, $J$How a managed apiary enterprise (e.g. a school apiary selling honey) identifies, prices, and hedges against loss and uncertainty — colony loss, weather, disease — as a small-scale instance of the same logic that prices any risk.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-apiary-risk-and-insurance","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('5031acba-d146-5142-9b8a-5b6cbaf2afcd', v_en_id, 'concept', $J$Associative Learning in Bees$J$, $J$A honeybee's demonstrated capacity to learn to associate a neutral stimulus (e.g. a scent) with a meaningful outcome (e.g. a sugar-water reward) after repeated pairing — classically shown via proboscis-extension-reflex (PER) conditioning, and attributed to the mushroom body, a brain structure supporting memory in a nervous system the size of a grass seed.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-associative-learning-in-bees","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('851eb6fc-9b1d-51f7-9661-6c0496f2a2a4', v_en_id, 'concept', $J$Computational Foraging Models$J$, $J$Simplified, rule-based algorithms — most directly the Artificial Bee Colony (ABC) algorithm — that model "employed," "onlooker," and "scout" agents searching a solution space the way real foraging bees search a landscape for nectar, applied to real optimization and routing problems.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-computational-foraging-models","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('795f98de-3669-5cce-81e2-71ac85f1edc7', v_en_id, 'concept', $J$Kin Selection and Altruism$J$, $J$Why an individual (e.g. a worker bee) can be favored by natural selection for forgoing its own reproduction to help a close relative (e.g. the queen) reproduce instead — because a gene that promotes this behavior can still increase in frequency via copies shared with relatives, not only via the helper's own direct offspring.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-kin-selection-and-altruism","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('be6a56f7-56f3-5ba3-a2ac-6f2165cf715e', v_en_id, 'concept', $J$Evolutionary Origins of Cooperation$J$, $J$Using Tinbergen's four questions (mechanism, development, function, evolutionary history) as a framework to sort competing explanations for a cooperative behavior, rather than treating "why" a behavior occurs as a single undifferentiated question.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-evolutionary-origins-of-cooperation","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('2ccca400-9d65-50cd-a808-196bee0c3ddc', v_en_id, 'concept', $J$Husbandry Philosophies (Conventional vs. Wesensgemäß)$J$, $J$How differing convictions about caring for a living system lead to genuinely different management decisions for the same colony — e.g. conventional beekeeping vs. "wesensgemäße" (nature-appropriate/anthroposophic) beekeeping, codified in Demeter guidelines and tracing to Rudolf Steiner and beekeeper Ferdinand Gerstung's term "der Bien."
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-husbandry-philosophies","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('98c3366e-b695-5df0-b0e9-f59f7bfb1bcf', v_en_id, 'concept', $J$Color Vision in Bees$J$, $J$A honeybee's demonstrated ability to discriminate flowers by hue rather than brightness alone — trichromatic vision shifted toward UV, blue, and green, unable to see red as a distinct color, and able to see UV nectar-guide patterns on flowers invisible to humans. First demonstrated behaviorally by Karl von Frisch, using a training paradigm that predates his later, better-known waggle-dance decoding.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-color-vision","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('92b90e8f-95e4-5bab-b8b8-2d06d2db3308', v_en_id, 'concept', $J$Counting and Numerosity in Bees$J$, $J$A honeybee's demonstrated capacity to discriminate small quantities (elements numbering roughly one to six) and to extrapolate a learned "greater than / less than" rule to correctly order a numerosity of zero below one — evidence of a basic, non-symbolic quantity representation in a brain of roughly one million neurons, not evidence of symbolic counting the way a human child counts.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-numerosity","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('f2537a05-e85d-5e87-9bd4-414131840a52', v_en_id, 'concept', $J$Worker Policing$J$, $J$The mechanisms by which a honeybee colony suppresses reproductive competition among its own workers — workers detect and destroy eggs laid by other workers rather than the queen, while queen mandibular pheromone independently suppresses worker ovary activation — keeping reproduction skewed toward the queen despite every worker retaining functional ovaries. The concrete mechanism behind the abstract claim, elsewhere in this LPM, that suppressing reproductive conflict is a precondition for colony-level cooperation.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-worker-policing","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('417f92d0-de73-58fc-9f5d-b65de6d2ec65', v_en_id, 'concept', $J$Nestmate Recognition$J$, $J$How guard bees at the hive entrance tell a colony member from an intruder — by antennating an arriving bee and comparing its cuticular hydrocarbon profile (a chemical "scent signature" acquired partly by contact with the colony's own comb wax) against a template, rejecting or attacking a bee whose profile doesn't match closely enough. A real, well-evidenced answer to "can bees fight?" — colony-boundary defense against intruders and robbing bees from other colonies, distinct from the within-colony reproductive conflict OE-CONCEPT-bee-k12-worker-policing addresses.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-nestmate-recognition","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('2c11461c-ceb4-53a0-93e1-7a51ec20507b', v_en_id, 'concept', $J$Bumblebee Social Learning$J$, $J$Bumblebees (Bombus terrestris — a different genus from the honeybee this LPM otherwise focuses on) can learn a novel, non-natural task by observing a trained demonstrator, and improve on the demonstrated technique rather than copying it exactly. More strikingly, bumblebees can socially transmit a two-step puzzle-box behavior that an untrained bee essentially never solves alone through individual trial-and-error — a documented case of social learning conveying a behavior "too complex to innovate alone" in an insect with roughly one million neurons.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-bumblebee-social-learning","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('22d2da9b-f04b-5fb1-a3ec-d1aded81f3e1', v_en_id, 'concept', $J$90 Percent Chimp, 10 Percent Bee$J$, $J$Jonathan Haidt's argument that human nature is mostly shaped by individual-level selection like a chimpanzee's (status-seeking, self-interested), but carries an additional, facultative capacity for group-level self-transcendence ("the hive switch") that activates under specific conditions (ritual, shared threat, synchronized activity) and makes people capable of team-player behavior more commonly associated with eusocial insects. An explicit analogy, not a claim of literal equivalence — Haidt himself cautions that "the psychology of bees has nothing in common with human psychology... I'm merely using bees as an illustration of how group-level selection creates team players."
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-90-percent-chimp-10-percent-bee","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('a4e588a7-3059-5629-b61b-da7a7b4fed5f', v_en_id, 'concept', $J$Integrated Pest Management (Varroa)$J$, $J$Deciding when and how to intervene against a pest — for a managed colony, most often the Varroa destructor mite — based on a measured infestation threshold rather than a fixed calendar, choosing between chemical (e.g. oxalic acid) and non-chemical (e.g. drone-brood removal, adapted bee strains) measures.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-integrated-pest-management","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$)
  ON CONFLICT (id) DO NOTHING;

  -- Strands and sub-strands
  INSERT INTO lpm_data_objects (id, project_id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ('bed43188-1bee-5e2b-a2c3-45615dc6cdee', v_en_id, $J$strand$J$, $J$The Hive as Superorganism$J$, $J$How a colony with no central leader nonetheless behaves, in important respects, as a single coordinated unit — through division of labor and decentralized group decision-making. The throughline concept (colony as superorganism) is introduced lightly in early grades, reinforced through the middle grades via division of labor and collective decision-making, and revisited at the top of the progression as the formal evolutionary- biology idea of a major transition in individuality.
$J$, $J$$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism","description":"How a colony with no central leader nonetheless behaves, in important respects, as a single coordinated unit — through division of labor and decentralized group decision-making. The throughline concept (colony as superorganism) is introduced lightly in early grades, reinforced through the middle grades via division of labor and collective decision-making, and revisited at the top of the progression as the formal evolutionary- biology idea of a major transition in individuality.\n","associatedDomains":["Biology","Mathematics","Computer Science","Ethics/Religion"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands)","relations":{"foundationalTo":["OE-STRAND-bee-k12-apiculture-craft-philosophy"],"parallel":["OE-STRAND-bee-k12-evolution-deep-time"]},"homeAnchors":[{"id":"cross-species-comparisons","label":"Cross-Species Comparisons","description":"Using another organism's behavior as comparison material to ask what it reveals about human behavior."},{"id":"cooperation-games","label":"Cooperation Games","description":"Simple game structures (payoff matrices, prisoner's-dilemma-style setups) used to reason about when cooperation pays off."},{"id":"governing-the-commons","label":"Governing the Commons","description":"How groups make binding decisions about a shared resource without a single designated leader."},{"id":"leaderless-decision-making","label":"Leaderless Decision-Making","description":"Group decision processes that reach consensus through distributed signals rather than a central authority."}],"thinkingTool":{"id":"payoff-matrices","label":"Payoff Matrices","description":"Tables that lay out the costs and benefits of different choices for different actors, used to reason about when cooperation is the better strategy.","status":"confirmed"},"essentialQuestion":{"broad":"What connects and distinguishes humans and other living things — and why?","worked":"A 