  ('df3f04ec-94cf-5118-8321-eb6b3c0cd7e1', v_en_id, $J$substrand$J$, $J$How Many Flowers?$J$, $J$Key concepts: Counting and Numerosity in Bees$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb3","performanceIndicators":["Describes, using the honeybee zero-ordering study as an example, that bees can be trained to discriminate small quantities (1–6 elements) and extend a learned rule to order zero below one."],"concepts":[{"id":"OE-CONCEPT-bee-k12-numerosity","emphasis":"primary"}],"required":false,"typicalGradeBand":"~10–12 (Kl. 5–6)","gradeBandId":"GB-3","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
