  ('aa888c99-1832-5d41-83d1-097e51b38326', v_en_id, $J$substrand$J$, $J$A Different Visible World$J$, $J$Key concepts: Color Vision in Bees, Counting and Numerosity in Bees$J$, $J$GB-5$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb5","performanceIndicators":["Explains that bee vision is trichromatic with sensitivity shifted toward UV, blue, and green, that bees cannot see red as a distinct color, and that bees can see UV nectar-guide patterns invisible to humans.","Compares a bee's sensory Umwelt to a human's using at least one concrete example (color vision or numerosity), and states one thing this comparison does and does not license concluding about a bee's inner experience."],"concepts":[{"id":"OE-CONCEPT-bee-k12-color-vision","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-numerosity","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~14–16 (Kl. 9–10)","gradeBandId":"GB-5","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('cddd7e52-bd01-58c2-9efa-5f01fc2af239', v_en_id, $J$substrand$J$, $J$From Foraging Behavior to Algorithm$J$, $J$Key concepts: Computational Foraging Models, Associative Learning in Bees, Bumblebee Social Learning$J$, $J$GB-6$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb6","performanceIndicators":["Builds a simplified version of an Artificial-Bee-Colony-style algorithm (employed/onlooker/scout roles searching a solution space) and compares its search behavior to real foraging bees.","Connects mushroom-body memory research to broader questions about how small nervous systems store learned associations, drawing at least one explicit comparison to human memory or intuition.","Uses the bumblebee ball-rolling and two-step puzzle-box findings to evaluate the claim that socially transmitting a behavior too complex to invent alone requires a large brain."],"concepts":[{"id":"OE-CONCEPT-bee-k12-computational-foraging-models","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-associative-learning-in-bees","emphasis":"reinforcing"},{"id":"OE-SANDBOX-CONCEPT-000004","emphasis":"reinforcing"},{"id":"OE-CONCEPT-bee-k12-bumblebee-social-learning","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~16–19 (Kl. 11–13)","gradeBandId":"GB-6","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('9637adac-3755-54de-b4db-0f6d664043ed', v_en_id, $J$strand$J$, $J$Bees Through Deep Time$J$, $J$Why cooperation of the kind seen in a bee colony evolves at all — from the simple observation that only the queen reproduces while every other bee helps raise her offspring, through the formal mechanism of kin selection, to Tinbergen's four questions as a framework for sorting competing explanations of a cooperative behavior, with an explicit comparison to the development of fairness behavior in human children.
$J$, $J$$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-evolution-deep-time","description":"Why cooperation of the kind seen in a bee colony evolves at all — from the simple observation that only the queen reproduces while every other bee helps raise her offspring, through the formal mechanism of kin selection, to Tinbergen's four questions as a framework for sorting competing explanations of a cooperative behavior, with an explicit comparison to the development of fairness behavior in human children.\n","associatedDomains":["Biology","Mathematics/Computer Science"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; primary weight at GB-4–GB-6)","relations":{"parallel":["OE-STRAND-bee-k12-cognition-swarm-intelligence"],"foundationalTo":["OE-STRAND-bee-k12-hive-superorganism"]},"homeAnchors":[{"id":"kin-selection","label":"Kin Selection","description":"Why individuals forgo their own reproduction to support the reproduction of close relatives."},{"id":"evolution-of-cooperation","label":"Evolution of Cooperation","description":"How cooperative behavior arises and is maintained over evolutionary time."},{"id":"causal-analysis-frameworks","label":"Causal Analysis Frameworks","description":"Structured ways (such as Tinbergen's four questions) of separating the different kinds of causes behind a behavior."},{"id":"altruism-across-species","label":"Altruism Across Species","description":"Comparing self-sacrificing or other-benefiting behavior across species, including in human development."}],"thinkingTool":{"id":"tinbergens-four-questions","label":"Tinbergen's Four Questions","description":"A framework for separating four distinct kinds of explanation for a behavior: immediate mechanism, developmental history, present-day function, and evolutionary origin.","status":"confirmed"},"essentialQuestion":{"broad":"What are the causes and consequences of an observed behavior?","worked":"Worker bees forgo their own reproduction to raise the queen's offspring. Which of Tinbergen's four questions do we reach for first when explaining human selflessness — and which do we usually skip?"},"epistemicStatus":"designed-thought-experiment","_source":{"repo":"bee-k12","path":"lpm/strands/strand-evolution-deep-time.yaml"}}$J$::jsonb, $J$draft$J$),
