  INSERT INTO projects (id, slug, name, description, status, epistemic_status, epistemic_status_note, hosting_mode, is_private, maturity, parent_project_id, focus_type, region_tags, theme_tags, working_languages)
  VALUES (
    v_de_id, 'bee-lpm-de', $J$Bee LPM (Deutsch)$J$,
    $J$Die deutschsprachige Bee LPM: sechs Stränge (Das Bienenvolk als Überorganismus; Bienen und ökologische Vernetzung; Wirtschaft und Recht einer Ressource; Bienen-Kognition & Schwarmintelligenz; Bienen durch die Tiefenzeit; Imkerei als Handwerk & Haltung), jeweils über sieben altersbasierte Klassenstufenbänder (GB-0 frühe Kindheit bis GB-6 gymnasiale Oberstufe). Standards-neutral konzipiert -- keine Klassenstufen- oder Standards-spezifische Sprache ist im Inhalt selbst verankert; eine Zuordnungsebene zu konkreten Schulsystemen lebt im bee-lpm-GitHub-Repository, nicht hier.$J$,
    'active', 'designed-thought-experiment',
    $J$Migrated from the standalone bee-k12 GitHub repo's bilingual /lpm/ tree, this language's fields only. Not field-tested or formally reviewed as curriculum -- designed-thought-experiment per RFC-0019, unchanged from the source repo's own status.$J$,
    'hosted', TRUE, 'draft', v_parent_id, 'thematic', '{}'::TEXT[], ARRAY['bees','interdisciplinary']::TEXT[], ARRAY['de']::TEXT[]
  )
  ON CONFLICT (slug) DO NOTHING;

