  IF v_user_id IS NOT NULL THEN
    INSERT INTO project_members (project_id, user_id, role) VALUES (v_de_id, v_user_id, 'owner') ON CONFLICT (project_id, user_id) DO NOTHING;
    UPDATE projects SET created_by = v_user_id WHERE id = v_de_id AND created_by IS NULL;
  END IF;

  -- Concept vocabulary (BEE-K12-v0.1.0)
  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
  VALUES
  ('9a8cb3ec-468e-533d-8862-2edfb9b3a523', v_de_id, 'concept', $J$Bienenvolk als Überorganismus$J$, $J$Ein Volk staatenbildender Insekten, dessen Mitglieder so funktional voneinander abhängig sind, dass das Volk als Ganzes Eigenschaften zeigt — koordinierte Entscheidungsfindung, Wachstum, Selbstreparatur, Fortpflanzung —, die eher einem einzelnen Organismus zugeschrieben werden als einem seiner einzelnen Mitglieder.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-superorganism","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('207fe6c3-f2ee-588b-9448-c6504a54d13d', v_de_id, 'concept', $J$Arbeitsteilung (altersabhängiger Polyethismus)$J$, $J$Innerhalb eines Volkes übernehmen einzelne Tiere unterschiedliche Aufgaben — oft in einer mit dem Alter vorhersagbar wechselnden Reihenfolge (Ammenbiene, Baubiene, Sammlerin) —, sodass die Gesamtarbeit des Volkes verteilt wird, statt dass jedes Mitglied jede Aufgabe übernimmt.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-division-of-labor","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('7ba6ee12-2501-5861-8b65-17842a82a451', v_de_id, 'concept', $J$Schwänzeltanz-Kommunikation$J$, $J$Ein in Achterform gemusterter Tanz, mit dem eine zurückkehrende Sammlerin ihren Stockgenossinnen Richtung und Entfernung einer Ressource (Futterquelle oder möglicher Nistplatz) mitteilt — entschlüsselt von Karl von Frisch (Nobelpreis für Physiologie oder Medizin 1973, gemeinsam mit Konrad Lorenz und Niko Tinbergen).
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-waggle-dance-communication","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('5094ad0d-9a9b-548e-80ec-69563597a53a', v_de_id, 'concept', $J$Schwarm-Entscheidungsfindung bei der Nistplatzwahl$J$, $J$Ein dezentraler Prozess — konkurrierende Schwänzeltänze der Kundschafterinnen und ein Schwellenwert-Quorum —, durch den ein Bienenschwarm gemeinsam einen einzigen neuen Nistplatz wählt, ohne dass ein einzelnes Tier die Entscheidung steuert.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-swarm-decision-making","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('9d95eb57-c62f-52a1-a618-362e15adb95b', v_de_id, 'concept', $J$Große Übergänge der Individualität$J$, $J$Der evolutionäre Prozess, durch den vormals eigenständige, sich selbst replizierende Einheiten (z. B. einzelne Insekten) beginnen, als eine einzelne übergeordnete Einheit zu reproduzieren und zu konkurrieren — wobei Konflikte zwischen den untergeordneten Einheiten so weit unterdrückt werden, dass natürliche Selektion überwiegend auf der übergeordneten Einheit wirkt.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-major-transitions-individuality","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('79ae361a-fdf9-5615-a362-8ce8c3ff38c3', v_de_id, 'concept', $J$Bestäubung$J$, $J$Die Übertragung von Pollen von den männlichen Strukturen einer Blüte auf eine empfängliche weibliche Struktur — oft auf einer anderen Pflanze —, wodurch Befruchtung und Samen-/Fruchtbildung ermöglicht werden. Tierbestäubung (u. a. durch Bienen) ist neben Wind- und Wasserbestäubung einer von mehreren Übertragungsmechanismen.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-pollination","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('78bde8b1-14e2-515d-881f-bad4ab60d1e0', v_de_id, 'concept', $J$Bestäubungsabhängigkeit$J$, $J$Das Ausmaß, in dem der Ertrag einer Nutzpflanze von tierischer Bestäubung statt Selbst- oder Windbestäubung abhängt — von Nutzpflanzen ohne jede Abhängigkeit bis zu Nutzpflanzen (z. B. Mandeln), die ohne sie fast vollständig ausfallen.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-pollination-dependency","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('6ccaaf36-bf9e-5cfd-8778-37728bab68b7', v_de_id, 'concept', $J$Ökosystemleistung$J$, $J$Ein Nutzen, den Menschen aus den fortlaufenden biologischen Prozessen eines Ökosystems ziehen — hier: tierische Bestäubung von Nahrungs- und Faserpflanzen — statt aus einem von Menschen direkt hergestellten Gut.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-ecosystem-service","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('b4ca9704-af11-5527-a7e2-848bd6124443', v_de_id, 'concept', $J$Gehaltene und wilde Bestäuber$J$, $J$Die Unterscheidung zwischen Honigbienenvölkern, die von Imkerinnen und Imkern aktiv gehalten und für Bestäubungsdienste transportiert werden, und der weitaus größeren Vielfalt wilder Bienen, anderer Insekten und tierischer Bestäuberarten — sowie die Abwägungen, wenn Erstere den Rückgang Letzterer ausgleichen sollen.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-managed-vs-wild-pollinators","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('a7bf810b-e1f1-5789-9d1f-b95c9750c963', v_de_id, 'concept', $J$Völker- und Bestäuberrückgang$J$, $J$Der vielursächliche Rückgang gehaltener Honigbienenvölker und wilder Bestäuberpopulationen (Lebensraumverlust, Pestizidbelastung, Parasiten/Erreger wie Varroa destructor und Klimawandel) sowie dessen Folgewirkungen für landwirtschaftliche Erträge und Ernährungssicherheit.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-colony-and-pollinator-decline","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('8eb4e3bd-8d47-51ec-b214-a910ecc3fc30', v_de_id, 'concept', $J$Bestäubungsmärkte$J$, $J$Der Kauf und Verkauf von Bestäubung als Dienstleistung — am sichtbarsten, wenn Imkerinnen und Imker gehaltene Völker gegen Bezahlung zu Betrieben transportieren (z. B. zur kalifornischen Mandelernte), statt dass ein Betrieb sich auf beiläufig stattfindende Bestäubung verlässt.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-pollination-markets","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('1ca7a8b5-7369-581d-be01-b3655588746c', v_de_id, 'concept', $J$Zeidler-Zunftrecht$J$, $J$Die eigene Zunft, das eigene Gericht und die besonderen Rechtsansprüche, die mittelalterliche Zeidler (wild- bzw. halbwild im Wald tätige Honigsammler) entwickelten — Honig und Wachs waren als Europas wichtigstes Süßungs- und Kerzenmaterial vor der Einführung von Rohrzucker wertvoll genug, um eine eigene Verwaltung statt allgemeinen Gewerberechts zu rechtfertigen.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-zeidler-guild-law","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('7e218e8f-d3e4-5283-8e49-73f2c07eaf6d', v_de_id, 'concept', $J$Verdrängung durch ein Ersatzgut$J$, $J$Was mit einem Gewerbe, Produkt oder einer regionalen Wirtschaft passiert, wenn ein Ersatzgut das Original verdrängt — so wie Rohrzucker (und später der Anbau von Zuckerrüben) nahezu die gesamte wirtschaftliche Bedeutung der Zeidlerei in Europa beseitigte.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-substitute-good-displacement","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('9db9777d-ed8f-5508-ac4c-136267882ec1', v_de_id, 'concept', $J$Bienenstand-Risiko und -Absicherung$J$, $J$Wie ein bewirtschafteter Bienenstand-Betrieb (z. B. ein Schulbienenstand mit Honigverkauf) Verlust und Unsicherheit — Völkerverlust, Wetter, Krankheit — erkennt, bepreist und absichert, als kleinmaßstäbliches Beispiel derselben Logik, mit der jedes Risiko bepreist wird.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-apiary-risk-and-insurance","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('09d0aaa2-da8e-5de0-9c4c-39222d0965a9', v_de_id, 'concept', $J$Assoziatives Lernen bei Bienen$J$, $J$Die nachgewiesene Fähigkeit einer Honigbiene, nach wiederholter Kopplung einen neutralen Reiz (z. B. einen Duft) mit einem bedeutsamen Ergebnis (z. B. einer Zuckerwasser-Belohnung) zu verknüpfen — klassisch gezeigt durch Rüsselreflex-Konditionierung (PER) und dem Pilzkörper zugeschrieben, einer gedächtnisunterstützenden Gehirnstruktur in einem Nervensystem von der Größe eines Grassamenkorns.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-associative-learning-in-bees","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('1560fb85-8704-5bfd-a94f-b2f1308dce6c', v_de_id, 'concept', $J$Computermodelle des Sammelverhaltens$J$, $J$Vereinfachte, regelbasierte Algorithmen — vor allem der Artificial-Bee-Colony-Algorithmus (ABC) —, die "beschäftigte", "beobachtende" und "kundschaftende" Agenten modellieren, die einen Lösungsraum so durchsuchen, wie reale Sammelbienen eine Landschaft nach Nektar absuchen, angewendet auf reale Optimierungs- und Routingprobleme.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-computational-foraging-models","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('bce29d21-5221-5a61-a279-903bc808e90e', v_de_id, 'concept', $J$Verwandtenselektion und Altruismus$J$, $J$Warum ein Individuum (z. B. eine Arbeiterin) durch natürliche Selektion begünstigt sein kann, wenn es auf eigenen Nachwuchs verzichtet, um stattdessen einem nahen Verwandten (z. B. der Königin) bei der Fortpflanzung zu helfen — weil ein Gen, das dieses Verhalten fördert, auch über mit Verwandten geteilte Kopien an Häufigkeit zunehmen kann, nicht nur über die eigenen direkten Nachkommen der Helferin.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-kin-selection-and-altruism","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('05c0cae0-c78f-5fd4-acca-8258ffbcf538', v_de_id, 'concept', $J$Evolutionäre Ursprünge der Kooperation$J$, $J$Tinbergens vier Fragen (Mechanismus, Entwicklung, Funktion, evolutionäre Geschichte) als Rahmenwerk nutzen, um konkurrierende Erklärungen für ein kooperatives Verhalten einzuordnen, statt die Frage nach dem "Warum" eines Verhaltens als eine einzige, undifferenzierte Frage zu behandeln.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-evolutionary-origins-of-cooperation","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('a749a4d4-81a2-5ebc-91a5-cc673e1cd848', v_de_id, 'concept', $J$Haltungsphilosophien (konventionell vs. wesensgemäß)$J$, $J$Wie unterschiedliche Überzeugungen über den Umgang mit einem lebendigen System zu tatsächlich unterschiedlichen Bewirtschaftungsentscheidungen für dasselbe Volk führen — z. B. konventionelle Imkerei im Vergleich zur wesensgemäßen (anthroposophischen) Bienenhaltung, kodifiziert in den Demeter-Richtlinien und zurückgehend auf Rudolf Steiner und den Imker Ferdinand Gerstung, die den Begriff „der Bien" prägten.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-husbandry-philosophies","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('fa345832-66de-53aa-805f-68696f575553', v_de_id, 'concept', $J$Farbensehen bei Bienen$J$, $J$Die nachgewiesene Fähigkeit einer Honigbiene, Blüten nach Farbton statt nur nach Helligkeit zu unterscheiden — trichromatisches Sehen mit Schwerpunkt auf UV, Blau und Grün, ohne die Fähigkeit, Rot als eigenständige Farbe zu erkennen, aber mit der Fähigkeit, für Menschen unsichtbare UV-Nektarmale auf Blüten zu sehen. Erstmals verhaltensbiologisch nachgewiesen von Karl von Frisch, mit einem Trainingsparadigma, das seiner späteren, bekannteren Entschlüsselung des Schwänzeltanzes vorausgeht.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-color-vision","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('d41839cc-be32-572d-9176-47ac2443fff4', v_de_id, 'concept', $J$Zählen und Mengenwahrnehmung bei Bienen$J$, $J$Die nachgewiesene Fähigkeit einer Honigbiene, kleine Mengen (etwa ein bis sechs Elemente) zu unterscheiden und eine gelernte "größer als / kleiner als"-Regel so zu erweitern, dass sie eine Menge von null korrekt unterhalb von eins einordnet — ein Beleg für eine grundlegende, nicht-symbolische Mengenrepräsentation in einem Gehirn von etwa einer Million Neuronen, kein Beleg für symbolisches Zählen, wie es ein Kind tut.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-numerosity","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('7618ac95-bf3a-57dc-8d10-e9c367694101', v_de_id, 'concept', $J$Arbeiterinnen-Policing$J$, $J$Die Mechanismen, mit denen ein Bienenvolk Fortpflanzungskonkurrenz zwischen den eigenen Arbeiterinnen unterdrückt — Arbeiterinnen erkennen und zerstören Eier, die von anderen Arbeiterinnen statt von der Königin gelegt wurden, während das Königinnen-Pheromon unabhängig davon die Eierstockaktivierung der Arbeiterinnen unterdrückt. Der konkrete Mechanismus hinter der an anderer Stelle in diesem LPM aufgestellten abstrakten Behauptung, dass die Unterdrückung von Fortpflanzungskonflikten eine Voraussetzung für Kooperation auf Volksebene ist.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-worker-policing","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('a6281a5a-a45f-5888-acad-4caff798c4f6', v_de_id, 'concept', $J$Nestgenossinnenerkennung$J$, $J$Wie Wächterinnen am Stockeingang ein Volksmitglied von einer Eindringlingin unterscheiden — durch Betasten mit den Antennen und Abgleich des chemischen "Duftprofils" (Kutikula-Kohlenwasserstoffe, teils durch Kontakt mit dem eigenen Wabenwachs erworben) mit einer Vorlage; bei zu starker Abweichung erfolgt Zurückweisung oder Angriff. Eine reale, gut belegte Antwort auf die Frage "können Bienen kämpfen?" — Verteidigung der Volksgrenze gegen Eindringlinge und räubernde Bienen anderer Völker, zu unterscheiden vom innervölkischen Fortpflanzungskonflikt, den OE-CONCEPT-bee-k12-worker-policing behandelt.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-nestmate-recognition","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('51f72dc7-a0e5-5052-8627-6d7812e8a13e', v_de_id, 'concept', $J$Soziales Lernen bei Hummeln$J$, $J$Hummeln (Bombus terrestris — eine andere Gattung als die in diesem LPM sonst behandelte Honigbiene) können eine neue, artfremde Aufgabe durch Beobachtung einer trainierten Demonstratorin erlernen und dabei die gezeigte Technik verbessern, statt sie exakt zu kopieren. Bemerkenswerter noch: Hummeln können ein zweistufiges Verhalten an einer Rätselbox sozial weitergeben, das eine untrainierte Hummel allein durch Ausprobieren so gut wie nie löst — ein dokumentierter Fall, in dem soziales Lernen bei einem Insekt mit rund einer Million Neuronen ein Verhalten vermittelt, das "zu komplex ist, um es allein zu erfinden."
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-bumblebee-social-learning","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('5f4c8d55-d658-56fa-96dd-79677a67f91b', v_de_id, 'concept', $J$90 Prozent Schimpanse, 10 Prozent Biene$J$, $J$Jonathan Haidts These, dass die menschliche Natur größtenteils durch individuelle Selektion geprägt ist wie die eines Schimpansen (statusorientiert, eigennützig), aber zusätzlich eine fakultative Fähigkeit zur gruppenbezogenen Selbsttranszendenz besitzt ("der Bienenstock-Schalter"), die unter bestimmten Bedingungen (Ritual, gemeinsame Bedrohung, synchrone Aktivität) aktiviert wird und Menschen zu einem Teamverhalten befähigt, wie es sonst eher staatenbildenden Insekten zugeschrieben wird. Eine ausdrückliche Analogie, kein Anspruch auf wörtliche Gleichsetzung — Haidt selbst warnt: "die Psychologie von Bienen hat nichts mit menschlicher Psychologie gemein... Ich nutze Bienen lediglich als Veranschaulichung dafür, wie Selektion auf Gruppenebene Teamspielerinnen hervorbringt."
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-90-percent-chimp-10-percent-bee","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('3eae2a7e-b6a1-57d4-b2c0-020921a152b8', v_de_id, 'concept', $J$Integrierter Schädlingsschutz (Varroa)$J$, $J$Entscheiden, wann und wie gegen einen Schädling eingegriffen wird — bei einem bewirtschafteten Volk am häufigsten die Varroamilbe (Varroa destructor) — anhand eines gemessenen Befallswerts statt eines festen Kalenders, mit einer Wahl zwischen chemischen (z. B. Oxalsäure) und nicht-chemischen (z. B. Drohnenbrutentnahme, angepasste Bienenlinien) Maßnahmen.
$J$, NULL, $J${"source_id":"OE-CONCEPT-bee-k12-integrated-pest-management","vocabulary":"BEE-K12-v0.1.0","_source":{"repo":"bee-k12","path":"lpm/vocabulary/BEE-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$)
  ON CONFLICT (id) DO NOTHING;

  -- Strands and sub-strands
  INSERT INTO lpm_data_objects (id, project_id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ('ed5a7bcb-7880-5064-8db8-fa90ecdcb766', v_de_id, $J$strand$J$, $J$Das Bienenvolk als Überorganismus$J$, $J$Wie ein Bienenvolk ohne zentrale Führung dennoch in wichtigen Aspekten als eine einzelne, koordinierte Einheit agiert — durch Arbeitsteilung und dezentrale Gruppenentscheidungen. Die Leitidee (Bienenvolk als Überorganismus) wird in den frühen Klassenstufen behutsam eingeführt, in den mittleren Klassenstufen durch Arbeitsteilung und kollektive Entscheidungsfindung vertieft und am oberen Ende der Progression als formale evolutionsbiologische Idee eines großen Übergangs der Individualität wieder aufgegriffen.
$J$, $J$$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism","description":"Wie ein Bienenvolk ohne zentrale Führung dennoch in wichtigen Aspekten als eine einzelne, koordinierte Einheit agiert — durch Arbeitsteilung und dezentrale Gruppenentscheidungen. Die Leitidee (Bienenvolk als Überorganismus) wird in den frühen Klassenstufen behutsam eingeführt, in den mittleren Klassenstufen durch Arbeitsteilung und kollektive Entscheidungsfindung vertieft und am oberen Ende der Progression als formale evolutionsbiologische Idee eines großen Übergangs der Individualität wieder aufgegriffen.\n","associatedDomains":["Biology","Mathematics","Computer Science","Ethics/Religion"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands)","relations":{"foundationalTo":["OE-STRAND-bee-k12-apiculture-craft-philosophy"],"parallel":["OE-STRAND-bee-k12-evolution-deep-time"]},"homeAnchors":[{"id":"cross-species-comparisons","label":"Artenvergleiche","description":"Das Verhalten eines anderen Lebewesens als Vergleichsmaterial nutzen, um zu fragen, was es über menschliches Verhalten verrät."},{"id":"cooperation-games","label":"Kooperationsspiele","description":"Einfache Spielstrukturen (Nutzenmatrizen, gefangenendilemma-artige Situationen), mit denen sich untersuchen lässt, wann sich Kooperation lohnt."},{"id":"governing-the-commons","label":"Verwaltung von Gemeingütern","description":"Wie Gruppen verbindliche Entscheidungen über eine gemeinsame Ressource treffen, ohne dass eine einzelne Person bestimmt."},{"id":"leaderless-decision-making","label":"Entscheidungen ohne Chefin","description":"Gruppenentscheidungsprozesse, die durch verteilte Signale statt durch eine zentrale Instanz zu einem gemeinsamen Ergebnis kommen."}],"thinkingTool":{"id":"payoff-matrices","label":"Nutzenmatrizen","description":"Tabellen, die Kosten und Nutzen verschiedener Entscheidungen für verschiedene Akteure gegenüberstellen, um zu untersuchen, wann Kooperation die bessere Strategie ist.","status":"confirmed"},"essentialQuestion":{"broad":"Was verbindet und unterscheidet Menschen und andere Lebewesen — und warum?","worked":"Ein Bienenvolk hat keine einzelne Chefin, trotzdem einigen sich vierzigtausend Bienen darauf, wo die nächste Wabe entsteht. Wie trifft eine Klasse eine gemeinsame Entscheidung, ohne dass eine Person einfach bestimmt — und was geht dabei jeweils verloren oder wird gewonnen?"},"epistemicStatus":"designed-thought-experiment","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('a268d274-d010-564a-8147-d1920df5f7e6', v_de_id, $J$substrand$J$, $J$Viele Bienen bemerken, einen Bienenstock$J$, $J$$J$, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb0","performanceIndicators":["Bemerkt durch direkte Beobachtung in der Nähe eines Bienenstocks oder bei einem Erntefest, dass sich viele Bienen gemeinsam um einen Bienenstock bewegen."],"concepts":[],"required":false,"typicalGradeBand":"~3–6 (Kita / PreK)","gradeBandId":"GB-0","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('82f4c16a-9083-5d5b-9070-025e516f61b3', v_de_id, $J$substrand$J$, $J$Das Volk handelt als Einheit$J$, $J$Schlüsselkonzepte: Bienenvolk als Überorganismus$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb1","performanceIndicators":["Beschreibt das Bienenvolk als eine gemeinsam entscheidende Einheit, nicht als Ansammlung einzeln handelnder Bienen.","Vergleicht den Bienenstock mit einem weiteren Beispiel, bei dem viele kleine Teile als ein Ganzes zusammenwirken (z. B. ein Ameisenbau, ein Team von Menschen)."],"concepts":[{"id":"OE-CONCEPT-bee-k12-superorganism","emphasis":"primary"}],"required":true,"typicalGradeBand":"~6–8 (Kl. 1–2)","gradeBandId":"GB-1","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('b204e39b-2045-5396-be72-ac6b575c6666', v_de_id, $J$substrand$J$, $J$Verschiedene Aufgaben, ein Volk$J$, $J$Schlüsselkonzepte: Arbeitsteilung (altersabhängiger Polyethismus), Bienenvolk als Überorganismus$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb2","performanceIndicators":["Vergleicht die unterschiedlichen Aufgaben, die Bienen innerhalb eines Volkes übernehmen, und erklärt, warum keine einzelne Biene alle davon übernimmt.","Wendet die Idee des Bienenvolks als Überorganismus auf ein neues Beispiel von Gruppenverhalten in der Natur an."],"concepts":[{"id":"OE-CONCEPT-bee-k12-division-of-labor","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-superorganism","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~8–10 (Kl. 3–4)","gradeBandId":"GB-2","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('0e5f6d54-5ab8-52fb-af5c-d13bd2dfa8d7', v_de_id, $J$substrand$J$, $J$Entscheiden ohne Chefin$J$, $J$Schlüsselkonzepte: Arbeitsteilung (altersabhängiger Polyethismus)$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb3","performanceIndicators":["Modelliert anhand einer einfachen Nutzenmatrix, wie einzelne Entscheidungen sich zu einer Gruppenentscheidung ohne zentrale Steuerung summieren.","Vergleicht die Arbeitsteilung in einem Bienenvolk mit der Arbeitsteilung in einer menschlichen Organisation, der die Schülerin oder der Schüler angehört."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-collective-intelligence","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-division-of-labor","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~10–12 (Kl. 5–6)","gradeBandId":"GB-3","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('df84c088-2709-53c9-8696-f43f7520ba98', v_de_id, $J$substrand$J$, $J$Wie sich die Botschaft verbreitet$J$, $J$Schlüsselkonzepte: Schwänzeltanz-Kommunikation, Schwarm-Entscheidungsfindung bei der Nistplatzwahl, Bienenvolk als Überorganismus$J$, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb4","performanceIndicators":["Erklärt, wie Winkel und Dauer des Schwänzeltanzes Richtung und Entfernung einer Ressource codieren.","Modelliert anhand eines einfachen Diagramms, wie konkurrierende Kundschafterinnen-Tänze und ein Schwellenwert-Quorum einem Schwarm erlauben, ohne zentrale Steuerung einen einzigen Nistplatz zu wählen.","Vergleicht den kollektiven Entscheidungsprozess des Bienenvolks mit einem menschlichen Gruppenentscheidungsprozess (z. B. eine Klassenabstimmung, eine Jury)."],"concepts":[{"id":"OE-CONCEPT-bee-k12-waggle-dance-communication","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-swarm-decision-making","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-superorganism","emphasis":"reinforcing"}],"required":false,"typicalGradeBand":"~12–14 (Kl. 7–8)","gradeBandId":"GB-4","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('59a8b7a4-4197-55fc-8325-558889316a62', v_de_id, $J$substrand$J$, $J$Arbeitsteilung als wirtschaftliche Idee$J$, $J$Schlüsselkonzepte: Arbeitsteilung (altersabhängiger Polyethismus)$J$, $J$GB-5$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb5","performanceIndicators":["Vergleicht die Arbeitsteilung in einem Bienenvolk mit der Spezialisierung in einer menschlichen Marktwirtschaft und benennt jeweils einen Vorteil und einen Nachteil der Spezialisierung."],"concepts":[{"id":"OE-CONCEPT-bee-k12-division-of-labor","emphasis":"reinforcing"}],"required":false,"typicalGradeBand":"~14–16 (Kl. 9–10)","gradeBandId":"GB-5","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('eca0d09f-272d-58c2-ba17-77ca3c9743e0', v_de_id, $J$substrand$J$, $J$Das Volk als Selektionseinheit$J$, $J$Schlüsselkonzepte: Große Übergänge der Individualität, 90 Prozent Schimpanse, 10 Prozent Biene, Bienenvolk als Überorganismus$J$, $J$GB-6$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-hive-superorganism-gb6","performanceIndicators":["Erklärt am Beispiel des Bienenvolks, wie vormals eigenständig reproduzierende Einheiten beginnen können, als eine einzelne übergeordnete Selektionseinheit zu funktionieren.","Verknüpft die in frühen Klassenstufen eingeführte Idee des Bienenvolks als Überorganismus mit dem formalen evolutionsbiologischen Konzept eines großen Übergangs der Individualität.","Bewertet je ein Argument dafür und dagegen, das Volk statt der einzelnen Biene als die primäre Einheit zu betrachten, auf die natürliche Selektion wirkt.","Erstellt ein Analogie-Mapping, das mindestens drei Merkmale (z. B. Kooperation, Konfliktunterdrückung, Grenz-/Nestgenossinnenerkennung, soziales Lernen) zwischen Bienen, Schimpansen und Menschen vergleicht und für jedes Merkmal ausdrücklich benennt, was sich entspricht und was nicht.","Erklärt Haidts These, Menschen seien \"90 Prozent Schimpanse und 10 Prozent Biene\", stellt sie ausdrücklich als Metapher statt als wörtliches Verhältnis dar (unter Bezug auf Haidts eigene Warnung, dass Bienen- und menschliche Psychologie nichts gemein haben), und benennt, welche von Tinbergens/SpeciesBases Erklärungsfragen (Mechanismus, Funktion, Phylogenie) die Metapher behandelt und welche offenbleiben.","Ordnet eine Reihe von Aussagen über die Analogie in 'integrierte Argumentation' versus benannte Fehlvorstellungen ein (Einzigartigkeitsverzerrung -- die Annahme, nur Menschen besäßen die Fähigkeit überhaupt; falsche Gleichsetzung -- die Bienen- und menschlichen Mechanismen als buchstäblich denselben Vorgang zu behandeln), nach demselben Fehlvorstellungs-Schema, das andernorts im OpenEvo-Ökosystem für artübergreifende Kognitionsbewertung verwendet wird."],"concepts":[{"id":"OE-CONCEPT-bee-k12-major-transitions-individuality","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-90-percent-chimp-10-percent-bee","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-superorganism","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-selection","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~16–19 (Kl. 11–13)","gradeBandId":"GB-6","_source":{"repo":"bee-k12","path":"lpm/strands/strand-hive-superorganism.yaml"}}$J$::jsonb, $J$draft$J$),
  ('cb3753da-e110-5a3a-97cd-7536a5eb8aba', v_de_id, $J$strand$J$, $J$Bienen und ökologische Vernetzung$J$, $J$Wie Bienen durch Bestäubung mit dem weiteren Nahrungsnetz verbunden sind — von der einfachen, sinnlichen Beobachtung, dass Bienen Blüten besuchen, über den biologischen Mechanismus der Bestäubung und die Idee einer Ökosystemleistung, bis hin zu den wirtschaftlichen und ernährungssicherheitsrelevanten Konsequenzen eines Ernährungssystems, das von tierischer Bestäubung abhängt — größtenteils durch gehaltene statt wilde Bienen.
$J$, $J$$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence","description":"Wie Bienen durch Bestäubung mit dem weiteren Nahrungsnetz verbunden sind — von der einfachen, sinnlichen Beobachtung, dass Bienen Blüten besuchen, über den biologischen Mechanismus der Bestäubung und die Idee einer Ökosystemleistung, bis hin zu den wirtschaftlichen und ernährungssicherheitsrelevanten Konsequenzen eines Ernährungssystems, das von tierischer Bestäubung abhängt — größtenteils durch gehaltene statt wilde Bienen.\n","associatedDomains":["Biology","Geography"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; primary weight at GB-5–GB-6)","relations":{"parallel":["OE-STRAND-bee-k12-economics-managed-resource"]},"homeAnchors":[{"id":"food-web-dependencies","label":"Nahrungsnetz-Abhängigkeiten","description":"Wie Organismen und Ernährungssysteme von Leistungen anderer Arten (etwa Bestäubung) abhängen."},{"id":"biodiversity-loss","label":"Verlust der Artenvielfalt","description":"Ursachen und Folgen abnehmender Artenvielfalt, einschließlich Folgewirkungen für bewirtschaftete Systeme."},{"id":"agricultural-systems","label":"Landwirtschaftliche Systeme","description":"Wie landwirtschaftliche Systeme um bestimmte ökologische Leistungen herum aufgebaut sind und dadurch von ihnen abhängig werden."},{"id":"responsibility-and-stewardship","label":"Verantwortung und Verwaltung","description":"Wer Verantwortung trägt, wenn eine gemeinsam genutzte ökologische Ressource beeinträchtigt oder erschöpft wird."}],"thinkingTool":{"id":"cause-maps","label":"Ursachenkarten","description":"Diagramme, die eine einzelne beobachtete Wirkung auf mehrere, unterschiedliche Arten von Ursachen zurückführen.","status":"confirmed"},"essentialQuestion":{"broad":"Wie lassen sich Erkenntnisse über menschliches Verhalten auf Nachhaltigkeit übertragen?","worked":"Ein großer Teil unserer Nahrungspflanzen profitiert zumindest teilweise von tierischer Bestäubung, vielfach durch gehaltene statt wilde Bienen. Was passiert mit einer Landwirtschaft, wenn gehaltene Bestäuber weniger werden — und wer trägt dafür Verantwortung?"},"epistemicStatus":"designed-thought-experiment","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('c6418a60-2fd1-5cb0-ad88-5ad599cbf619', v_de_id, $J$substrand$J$, $J$Bienen besuchen Blüten$J$, $J$$J$, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb0","performanceIndicators":["Bemerkt durch direkte Beobachtung, dass Bienen von Blüte zu Blüte fliegen und dabei oft sichtbaren Pollen tragen."],"concepts":[],"required":false,"typicalGradeBand":"~3–6 (Kita / PreK)","gradeBandId":"GB-0","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('142118e4-7015-5358-9510-a5d89af467d7', v_de_id, $J$substrand$J$, $J$Von der Blüte zur Frucht$J$, $J$Schlüsselkonzepte: Bestäubung$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb1","performanceIndicators":["Beschreibt in einfachen Worten, dass eine Biene Pollen von einer Blüte zur nächsten trägt und dass dies einer neuen Frucht oder einem neuen Samen beim Wachsen hilft."],"concepts":[{"id":"OE-CONCEPT-bee-k12-pollination","emphasis":"primary"}],"required":true,"typicalGradeBand":"~6–8 (Kl. 1–2)","gradeBandId":"GB-1","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('f76d2d1f-c276-5508-961b-90b996b9b453', v_de_id, $J$substrand$J$, $J$Woher unser Essen kommt$J$, $J$Schlüsselkonzepte: Ökosystemleistung, Bestäubung$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb2","performanceIndicators":["Verfolgt ein Lebensmittel auf dem Tisch zurück zu einer Blüte, die vermutlich von einer Biene oder einem anderen Tier bestäubt wurde.","Benennt Bestäubung als ein Beispiel für eine Leistung der Natur, die Menschen nicht selbst hergestellt haben."],"concepts":[{"id":"OE-CONCEPT-bee-k12-ecosystem-service","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-pollination","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~8–10 (Kl. 3–4)","gradeBandId":"GB-2","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('41f7e128-4bb1-5035-8daf-91c13f23b913', v_de_id, $J$substrand$J$, $J$Bienen unter anderen Bestäubern$J$, $J$Schlüsselkonzepte: Bestäubung$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb3","performanceIndicators":["Benennt mindestens ein weiteres bestäubendes Tier neben der Honigbiene (z. B. eine Wildbiene, einen Schmetterling oder eine Fledermaus) und vergleicht es kurz mit der Honigbiene."],"concepts":[{"id":"OE-CONCEPT-bee-k12-pollination","emphasis":"reinforcing"}],"required":false,"typicalGradeBand":"~10–12 (Kl. 5–6)","gradeBandId":"GB-3","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('93a6a7fd-ea12-53ca-bc7e-fd46def64329', v_de_id, $J$substrand$J$, $J$(an dieser Stufe nicht belegt)$J$, $J$$J$, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb4","performanceIndicators":[],"concepts":[],"required":false,"typicalGradeBand":"~12–14 (Kl. 7–8)","gradeBandId":"GB-4","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('1e0162c2-13f8-54c1-b717-8b19469a0cf8', v_de_id, $J$substrand$J$, $J$Ein Ernährungssystem, das von Bestäubung abhängt$J$, $J$Schlüsselkonzepte: Bestäubungsabhängigkeit, Gehaltene und wilde Bestäuber, Ökosystemleistung$J$, $J$GB-5$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb5","performanceIndicators":["Erklärt anhand eines konkreten Beispiels (z. B. Mandeln), warum eine Nutzpflanze von tierischer Bestäubung abhängt, und schätzt ab, was auf dem Spiel steht, wenn diese Bestäubung ausbleibt.","Vergleicht die Rolle gehaltener Honigbienenvölker mit der wilder Bestäuber für den Erhalt landwirtschaftlicher Erträge und nennt mindestens eine reale Kennzahl (z. B. die IPBES-Schätzung, dass etwa drei Viertel der Nahrungspflanzen zumindest teilweise von tierischer Bestäubung profitieren)."],"concepts":[{"id":"OE-CONCEPT-bee-k12-pollination-dependency","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-managed-vs-wild-pollinators","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-ecosystem-service","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~14–16 (Kl. 9–10)","gradeBandId":"GB-5","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('dc6279fa-8f57-5a6f-bd3c-e400ae3453a1', v_de_id, $J$substrand$J$, $J$Bestäuberrückgang und Ernährungssicherheit$J$, $J$Schlüsselkonzepte: Völker- und Bestäuberrückgang, Bestäubungsabhängigkeit, Gehaltene und wilde Bestäuber$J$, $J$GB-6$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-ecological-interdependence-gb6","performanceIndicators":["Benennt mindestens drei unterschiedliche Ursachen für Völker- und Bestäuberrückgang (z. B. Lebensraumverlust, Pestizidbelastung, Varroa destructor, Klimawandel) und erklärt, dass keine einzelne Ursache allein ausreicht.","Bewertet eine vorgeschlagene politische oder bewirtschaftliche Reaktion auf den Bestäuberrückgang danach, wer ihre Kosten trägt und wer von ihr profitiert."],"concepts":[{"id":"OE-CONCEPT-bee-k12-colony-and-pollinator-decline","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-pollination-dependency","emphasis":"reinforcing"},{"id":"OE-CONCEPT-bee-k12-managed-vs-wild-pollinators","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~16–19 (Kl. 11–13)","gradeBandId":"GB-6","_source":{"repo":"bee-k12","path":"lpm/strands/strand-ecological-interdependence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('93a73e97-0bd7-53ff-ba48-0698932fd4a5', v_de_id, $J$strand$J$, $J$Wirtschaft und Recht einer Ressource$J$, $J$Wie eine biologische Ressource — Bestäubung, Honig, Wachs — wertvoll genug wird, um eigene Märkte, Zünfte, Gerichte und ein eigenes Risikomanagement zu benötigen. Konzentriert am oberen Ende der Progression (GB-5/GB-6), wo Wirtschaft und Geschichte erstmals als eigene Fächer auftreten, statt wie die Stränge A und B über viele Klassenstufen verteilt zu sein.
$J$, $J$$J$, $J$Economics/Civics$J$, $J${"source_id":"OE-STRAND-bee-k12-economics-managed-resource","description":"Wie eine biologische Ressource — Bestäubung, Honig, Wachs — wertvoll genug wird, um eigene Märkte, Zünfte, Gerichte und ein eigenes Risikomanagement zu benötigen. Konzentriert am oberen Ende der Progression (GB-5/GB-6), wo Wirtschaft und Geschichte erstmals als eigene Fächer auftreten, statt wie die Stränge A und B über viele Klassenstufen verteilt zu sein.\n","associatedDomains":["Economics/Civics","History"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; carries real weight only at GB-5–GB-6)","relations":{"parallel":["OE-STRAND-bee-k12-ecological-interdependence"]},"homeAnchors":[{"id":"markets-for-ecosystem-services","label":"Märkte für Ökosystemleistungen","description":"Wie eine natürlich vorkommende Leistung (wie Bestäubung) zu einer bepreisten, handelbaren Dienstleistung wird."},{"id":"commons-governance-historical","label":"Historische Gemeingut-Verwaltung","description":"Historische Institutionen (Zünfte, eigene Gerichte), mit denen Gesellschaften eine wertvolle gemeinsame Ressource verwalteten."},{"id":"substitute-goods-and-obsolescence","label":"Ersatzgüter und Bedeutungsverlust","description":"Was mit einem Gewerbe, Produkt oder einer regionalen Wirtschaft passiert, wenn ein Ersatzprodukt das Ausgangsprodukt verdrängt."},{"id":"risk-and-insurance","label":"Risiko und Versicherung","description":"Wie bewirtschaftete Betriebe (etwa ein Schulbienenstand) Verlust und Unsicherheit bepreisen und absichern."}],"thinkingTool":{"id":"cause-maps","label":"Ursachenkarten","description":"Diagramme, die eine einzelne beobachtete Wirkung auf mehrere, unterschiedliche Arten von Ursachen zurückführen.","status":"confirmed"},"essentialQuestion":{"broad":"Was können Gemeinschaften, die eine gemeinsame Ressource verwalten, uns lehren?","worked":"Mittelalterliche Zeidler hatten eine eigene Zunft, ein eigenes Gericht und besondere Rechte — weil Honig und Wachs wertvoll genug waren, um eigene Regeln zu brauchen. Was passiert mit einem Gewerbe, wenn ein Ersatzprodukt das Ausgangsprodukt überflüssig macht?"},"epistemicStatus":"designed-thought-experiment","_source":{"repo":"bee-k12","path":"lpm/strands/strand-economics-managed-resource.yaml"}}$J$::jsonb, $J$draft$J$),
