  ('85ce36dc-81c1-5735-b346-24eeb1fa0760', v_de_id, $J$substrand$J$, $J$(an dieser Stufe nicht belegt)$J$, $J$$J$, $J$GB-3$J$, $J$Economics/Civics$J$, $J${"source_id":"OE-STRAND-bee-k12-economics-managed-resource-gb3","performanceIndicators":[],"concepts":[],"required":false,"typicalGradeBand":"~10–12 (Kl. 5–6)","gradeBandId":"GB-3","_source":{"repo":"bee-k12","path":"lpm/strands/strand-economics-managed-resource.yaml"}}$J$::jsonb, $J$draft$J$),
  ('b8ad1346-1bb1-54f3-bf09-c8a7305352db', v_de_id, $J$substrand$J$, $J$(an dieser Stufe nicht belegt)$J$, $J$$J$, $J$GB-4$J$, $J$Economics/Civics$J$, $J${"source_id":"OE-STRAND-bee-k12-economics-managed-resource-gb4","performanceIndicators":[],"concepts":[],"required":false,"typicalGradeBand":"~12–14 (Kl. 7–8)","gradeBandId":"GB-4","_source":{"repo":"bee-k12","path":"lpm/strands/strand-economics-managed-resource.yaml"}}$J$::jsonb, $J$draft$J$),
  ('4bf42cec-e991-51f5-a096-a4c7a89bd49a', v_de_id, $J$substrand$J$, $J$Eine Ressource, die eigene Regeln braucht$J$, $J$Schlüsselkonzepte: Bestäubungsmärkte, Zeidler-Zunftrecht$J$, $J$GB-5$J$, $J$Economics/Civics$J$, $J${"source_id":"OE-STRAND-bee-k12-economics-managed-resource-gb5","performanceIndicators":["Erklärt, wie Bestäubung zu einer bezahlten Dienstleistung wurde (z. B. transportierte Völker für die kalifornische Mandelernte), und berechnet ein einfaches Angebots-Nachfrage-Szenario für einen Bestäubungsmarkt.","Beschreibt, warum das mittelalterliche Zeidler-Gewerbe eine eigene Zunft und ein eigenes Gericht entwickelte (z. B. das Zeidelgericht in Feucht, aktiv vom späten 13. bis späten 18. Jahrhundert), und benennt die Bedingungen, unter denen eine Ressource wertvoll genug für eine eigene Verwaltung wird.","Benennt eine weitere historische oder moderne Institution (Zunft, Genossenschaft, Aufsichtsbehörde), die den Zugang zu einer wertvollen gemeinsamen Ressource regelt, und vergleicht sie mit dem Zeidler-Zunftrecht."],"concepts":[{"id":"OE-CONCEPT-bee-k12-pollination-markets","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-zeidler-guild-law","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-institutions","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~14–16 (Kl. 9–10)","gradeBandId":"GB-5","_source":{"repo":"bee-k12","path":"lpm/strands/strand-economics-managed-resource.yaml"}}$J$::jsonb, $J$draft$J$),
  ('b250eb46-13f8-50ac-a9e1-71c2d60522cc', v_de_id, $J$substrand$J$, $J$Wenn ein Ersatzprodukt das Original verdrängt$J$, $J$Schlüsselkonzepte: Verdrängung durch ein Ersatzgut, Bienenstand-Risiko und -Absicherung, Bestäubungsmärkte$J$, $J$GB-6$J$, $J$Economics/Civics$J$, $J${"source_id":"OE-STRAND-bee-k12-economics-managed-resource-gb6","performanceIndicators":["Analysiert anhand des Niedergangs der Zeidlerei nach der Verfügbarkeit von Rohrzucker (und später Zuckerrübe), was mit einer regionalen Wirtschaft passiert, wenn ein Ersatzprodukt das Ausgangsprodukt verdrängt, und überträgt das Muster auf ein weiteres historisches oder aktuelles Beispiel.","Kalkuliert die Wirtschaftlichkeit eines kleinen bewirtschafteten Bienenstands (z. B. den Honigverkauf des Schulbienenstands), einschließlich mindestens zweier unterschiedlicher Risikofaktoren (z. B. Völkerverlust, Wetter, Krankheit) und wie eine Imkerin oder ein Imker sich jeweils dagegen absichern könnte."],"concepts":[{"id":"OE-CONCEPT-bee-k12-substitute-good-displacement","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-apiary-risk-and-insurance","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-pollination-markets","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~16–19 (Kl. 11–13)","gradeBandId":"GB-6","_source":{"repo":"bee-k12","path":"lpm/strands/strand-economics-managed-resource.yaml"}}$J$::jsonb, $J$draft$J$),
  ('b55c8d52-6888-5c00-a84a-126320ea8a17', v_de_id, $J$strand$J$, $J$Bienen-Kognition & Schwarmintelligenz$J$, $J$Was ein Gehirn von der Größe eines Grassamenkorns leisten kann und was nicht — von der Beobachtung, dass eine Biene sich scheinbar an eine gute Blüte erinnert, über den tatsächlichen Mechanismus assoziativen Lernens (Rüsselreflex-Konditionierung, Pilzkörper) bis zu Computermodellen (dem Artificial-Bee-Colony-Algorithmus), die kollektives Sammelverhalten in Algorithmen übersetzen, die reale Optimierungsprobleme lösen.
$J$, $J$$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence","description":"Was ein Gehirn von der Größe eines Grassamenkorns leisten kann und was nicht — von der Beobachtung, dass eine Biene sich scheinbar an eine gute Blüte erinnert, über den tatsächlichen Mechanismus assoziativen Lernens (Rüsselreflex-Konditionierung, Pilzkörper) bis zu Computermodellen (dem Artificial-Bee-Colony-Algorithmus), die kollektives Sammelverhalten in Algorithmen übersetzen, die reale Optimierungsprobleme lösen.\n","associatedDomains":["Biology","Mathematics/Computer Science","Physics"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; primary weight at GB-4–GB-6)","relations":{"parallel":["OE-STRAND-bee-k12-hive-superorganism","OE-STRAND-bee-k12-evolution-deep-time"]},"homeAnchors":[{"id":"associative-learning","label":"Assoziatives Lernen","description":"Wie ein Lebewesen lernt, einen neutralen Reiz durch wiederholte Kopplung mit einem bedeutsamen Ergebnis zu verknüpfen."},{"id":"small-brain-cognition","label":"Kognition im winzigen Gehirn","description":"Was ein sehr kleines Nervensystem leisten kann und was nicht — und was das allgemein über Kognition verrät."},{"id":"computational-models-of-behavior","label":"Computermodelle von Verhalten","description":"Ein beobachtetes biologisches Verhalten in einen Algorithmus übersetzen, der eine reale informatische Aufgabe löst."},{"id":"heuristics-vs-planning","label":"Faustregeln versus Planung","description":"Wann eine einfache, oft wiederholte Regel eine einzelne durchdachte Planung schlägt."},{"id":"perceptual-worlds-umwelt","label":"Wahrnehmungswelten (Umwelt)","description":"Wie stark sich die sinnliche Umwelt einer Art von der menschlichen unterscheiden kann — anhand einer belegten Sinnesfähigkeit (z. B. UV-Farbsehen) konkret statt abstrakt gemacht."}],"thinkingTool":{"id":"computational-agent-based-models","label":"Computermodelle / agentenbasierte Modelle","description":"Vereinfachte, regelbasierte Simulationen (etwa der Artificial-Bee-Colony-Algorithmus), die mit vielen einfachen Agenten ein komplexes Gruppenverhalten nachbilden.","status":"draft"},"essentialQuestion":{"broad":"Was verraten uns unsere eigenen Gedanken und Intuitionen?","worked":"Das Gehirn einer Honigbiene ist so groß wie ein Grassamenkorn — trotzdem lernt sie in wenigen Versuchen, einen Duft mit einer Belohnung zu verknüpfen. Wo im eigenen Leben schlägt eine einfache, oft wiederholte Regel eine einzelne kluge Planung?"},"epistemicStatus":"designed-thought-experiment","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('4a1f1f4e-d07c-5755-aefd-2ec8d8660b63', v_de_id, $J$substrand$J$, $J$(an dieser Stufe nicht belegt)$J$, $J$$J$, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb0","performanceIndicators":[],"concepts":[],"required":false,"typicalGradeBand":"~3–6 (Kita / PreK)","gradeBandId":"GB-0","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('0931767b-2f13-546d-a59a-994dfb4e25ae', v_de_id, $J$substrand$J$, $J$Bienen mögen diese Farbe$J$, $J$$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb1","performanceIndicators":["Bemerkt anhand eines einfachen Klassenzimmer-Futterstellen-Experiments (farbige Futterstellen im Vergleich zu grauen), dass Bienen wiederholt zu einer bestimmten Farbe zurückkehren."],"concepts":[],"required":false,"typicalGradeBand":"~6–8 (Kl. 1–2)","gradeBandId":"GB-1","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('18f52eeb-503e-5db0-8420-2a2e0bbfb293', v_de_id, $J$substrand$J$, $J$Eine Biene scheint sich zu erinnern$J$, $J$$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb2","performanceIndicators":["Bemerkt durch direkte Beobachtung oder ein einfaches Futterstellen-Experiment, dass eine Biene wiederholt zu einer bereits besuchten Futterquelle zurückkehrt."],"concepts":[],"required":false,"typicalGradeBand":"~8–10 (Kl. 3–4)","gradeBandId":"GB-2","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('b4ba5953-8e5f-53a4-bb62-803164d066ba', v_de_id, $J$substrand$J$, $J$Wie viele Blüten?$J$, $J$Schlüsselkonzepte: Zählen und Mengenwahrnehmung bei Bienen$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb3","performanceIndicators":["Beschreibt anhand der Studie zur Null-Einordnung bei Honigbienen, dass Bienen darauf trainiert werden können, kleine Mengen (1–6 Elemente) zu unterscheiden, und eine gelernte Regel so erweitern, dass sie null unterhalb von eins einordnen."],"concepts":[{"id":"OE-CONCEPT-bee-k12-numerosity","emphasis":"primary"}],"required":false,"typicalGradeBand":"~10–12 (Kl. 5–6)","gradeBandId":"GB-3","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('b7066520-1859-596a-b060-589e30abcf16', v_de_id, $J$substrand$J$, $J$Lernen in einem winzigen Gehirn$J$, $J$Schlüsselkonzepte: Assoziatives Lernen bei Bienen$J$, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb4","performanceIndicators":["Beschreibt die Rüsselreflex-Konditionierung (PER) als Beleg dafür, dass ein sehr kleines Gehirn zu echtem assoziativem Lernen fähig ist.","Benennt den Pilzkörper als die für diese Art von Gedächtnis hauptsächlich verantwortliche Gehirnstruktur."],"concepts":[{"id":"OE-CONCEPT-bee-k12-associative-learning-in-bees","emphasis":"primary"}],"required":true,"typicalGradeBand":"~12–14 (Kl. 7–8)","gradeBandId":"GB-4","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('1e7fe32d-da2f-5518-8cb9-3df91072ca48', v_de_id, $J$substrand$J$, $J$Eine andere sichtbare Welt$J$, $J$Schlüsselkonzepte: Farbensehen bei Bienen, Zählen und Mengenwahrnehmung bei Bienen$J$, $J$GB-5$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb5","performanceIndicators":["Erklärt, dass das Bienenauge trichromatisch mit Schwerpunkt auf UV, Blau und Grün ist, dass Bienen Rot nicht als eigenständige Farbe erkennen können und dass Bienen für Menschen unsichtbare UV-Nektarmale sehen können.","Vergleicht die sinnliche Umwelt einer Biene mit der eines Menschen anhand mindestens eines konkreten Beispiels (Farbsehen oder Mengenwahrnehmung) und benennt, was dieser Vergleich über das Innenleben einer Biene aussagen darf und was nicht."],"concepts":[{"id":"OE-CONCEPT-bee-k12-color-vision","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-numerosity","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~14–16 (Kl. 9–10)","gradeBandId":"GB-5","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('c7803f94-aad7-5754-8b6d-1e70e79b485f', v_de_id, $J$substrand$J$, $J$Von Sammelverhalten zum Algorithmus$J$, $J$Schlüsselkonzepte: Computermodelle des Sammelverhaltens, Assoziatives Lernen bei Bienen, Soziales Lernen bei Hummeln$J$, $J$GB-6$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-cognition-swarm-intelligence-gb6","performanceIndicators":["Baut eine vereinfachte Version eines Artificial-Bee-Colony-artigen Algorithmus (Beschäftigte, Beobachterinnen, Kundschafterinnen durchsuchen einen Lösungsraum) und vergleicht dessen Suchverhalten mit dem realer Sammelbienen.","Verknüpft die Pilzkörper-Gedächtnisforschung mit weiterreichenden Fragen dazu, wie kleine Nervensysteme gelernte Assoziationen speichern, und zieht mindestens einen expliziten Vergleich zum menschlichen Gedächtnis oder zur Intuition.","Nutzt die Befunde zum Ballrollen und zur zweistufigen Rätselbox bei Hummeln, um die These zu bewerten, dass die soziale Weitergabe eines allein zu komplexen Verhaltens ein großes Gehirn voraussetzt."],"concepts":[{"id":"OE-CONCEPT-bee-k12-computational-foraging-models","emphasis":"primary"},{"id":"OE-CONCEPT-bee-k12-associative-learning-in-bees","emphasis":"reinforcing"},{"id":"OE-SANDBOX-CONCEPT-000004","emphasis":"reinforcing"},{"id":"OE-CONCEPT-bee-k12-bumblebee-social-learning","emphasis":"reinforcing"}],"required":true,"typicalGradeBand":"~16–19 (Kl. 11–13)","gradeBandId":"GB-6","_source":{"repo":"bee-k12","path":"lpm/strands/strand-cognition-swarm-intelligence.yaml"}}$J$::jsonb, $J$draft$J$),
  ('5d6afe40-e0a8-5e48-ad30-0a23f6e46b93', v_de_id, $J$strand$J$, $J$Bienen durch die Tiefenzeit$J$, $J$Warum Kooperation, wie sie in einem Bienenvolk zu beobachten ist, überhaupt entsteht — von der einfachen Beobachtung, dass nur die Königin sich fortpflanzt, während alle anderen Bienen bei der Aufzucht ihrer Nachkommen helfen, über den formalen Mechanismus der Verwandtenselektion bis zu Tinbergens vier Fragen als Rahmenwerk, um konkurrierende Erklärungen für ein kooperatives Verhalten einzuordnen — mit einem expliziten Vergleich zur Entwicklung von Fairness-Verhalten bei Kindern.
$J$, $J$$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-bee-k12-evolution-deep-time","description":"Warum Kooperation, wie sie in einem Bienenvolk zu beobachten ist, überhaupt entsteht — von der einfachen Beobachtung, dass nur die Königin sich fortpflanzt, während alle anderen Bienen bei der Aufzucht ihrer Nachkommen helfen, über den formalen Mechanismus der Verwandtenselektion bis zu Tinbergens vier Fragen als Rahmenwerk, um konkurrierende Erklärungen für ein kooperatives Verhalten einzuordnen — mit einem expliziten Vergleich zur Entwicklung von Fairness-Verhalten bei Kindern.\n","associatedDomains":["Biology","Mathematics/Computer Science"],"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; primary weight at GB-4–GB-6)","relations":{"parallel":["OE-STRAND-bee-k12-cognition-swarm-intelligence"],"foundationalTo":["OE-STRAND-bee-k12-hive-superorganism"]},"homeAnchors":[{"id":"kin-selection","label":"Verwandtenselektion","description":"Warum Individuen auf eigenen Nachwuchs verzichten, um die Fortpflanzung naher Verwandter zu unterstützen."},{"id":"evolution-of-cooperation","label":"Evolution der Kooperation","description":"Wie kooperatives Verhalten über evolutionäre Zeiträume entsteht und erhalten bleibt."},{"id":"causal-analysis-frameworks","label":"Rahmenwerke zur Ursachenanalyse","description":"Strukturierte Wege (etwa Tinbergens vier Fragen), die verschiedenen Ursachenarten hinter einem Verhalten zu trennen."},{"id":"altruism-across-species","label":"Altruismus im Artenvergleich","description":"Selbstloses oder anderen nützendes Verhalten artübergreifend vergleichen, auch in der menschlichen Entwicklung."}],"thinkingTool":{"id":"tinbergens-four-questions","label":"Tinbergens vier Fragen","description":"Ein Rahmenwerk, das vier unterschiedliche Erklärungsarten für ein Verhalten trennt: unmittelbarer Mechanismus, Entwicklung im Lebenslauf, heutiger Nutzen und evolutionäre Entstehung.","status":"confirmed"},"essentialQuestion":{"broad":"Was sind Ursachen und Folgen eines beobachteten Verhaltens?","worked":"Arbeiterinnen verzichten auf eigenen Nachwuchs, um den der Königin großzuziehen. Welche von Tinbergens vier Fragen stellen wir uns zuerst, wenn wir menschliche Selbstlosigkeit erklären — und welche übergehen wir meist?"},"epistemicStatus":"designed-thought-experiment","_source":{"repo":"bee-k12","path":"lpm/strands/strand-evolution-deep-time.yaml"}}$J$::jsonb, $J$draft$J$),
